import { chromium } from 'playwright-core';
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium' });
const p = await (await browser.newContext()).newPage();
await p.goto(process.argv[2]);
const trigger = p.getByRole('combobox', { name: 'Category' });
await trigger.focus();
const state = () => p.evaluate(() => ({
  active: document.activeElement?.textContent?.slice(0, 30),
  role: document.activeElement?.getAttribute('role'),
  highlighted: [...document.querySelectorAll('[data-highlighted]')].map((e) => e.textContent),
  open: !!document.querySelector('[role="listbox"]'),
}));
for (const key of ['Enter', 'ArrowDown', 'ArrowDown', 'ArrowDown', 'Enter']) {
  await p.keyboard.press(key);
  await p.waitForTimeout(150);
  console.log(key, JSON.stringify(await state()), await trigger.innerText());
}
await browser.close();
